def can_form_palindrome(s):
    freq = {}
    for char in s:
        if char in freq:
            freq[char] += 1
        else:
            freq[char] = 1

    odd_count = 0
    for count in freq.values():
        if count % 2 != 0:
            odd_count += 1

    return odd_count <= 1

def min_operations_to_palindrome(s):
    n = len(s)
    s = list(s)
    operations = 0

    left = 0
    right = n - 1

    while left < right:
        if s[left] == s[right]:
            left += 1
            right -= 1
        else:
            l = left
            r = right
            while r > l and s[r] != s[l]:
                r -= 1

            if r == l:
                # Swap s[l] with s[l+1]
                s[l], s[l+1] = s[l+1], s[l]
                operations += 1
            else:
                # Swap s[r] with s[r+1] to the right until it reaches s[right]
                while r < right:
                    s[r], s[r+1] = s[r+1], s[r]
                    r += 1
                    operations += 1
                left += 1
                right -= 1

    return operations

